INSERT INTO `movimientos` (`causaId`, `fecha`, `tipo`, `descripcion`, `textoCliente`, `visible`, `anulado`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES (@causa, '2024-04-10', 'escrito_presentado', 'Se presenta demanda por daños y perjuicios derivados del accidente de tránsito del 12/09/2023. Se ofrece prueba documental, testimonial, pericial mecánica y pericial médica. Se cita en garantía a Seguros La Ribera S.A.', 'Presentamos la demanda ante el juzgado. Le vamos a avisar cuando la empresa sea notificada.', 1, 0, @u_julian, '2024-04-10 10:20:40.138911', NULL, NULL);
INSERT INTO `movimiento_cambios` (`movimientoId`, `accion`, `usuarioId`, `fechaHora`, `cambios`) VALUES (@movimiento, 'carga', @u_julian, '2024-04-10 10:20:40.138911', '[{"campo":"fecha","anterior":null,"nuevo":"2024-04-10"},{"campo":"tipo","anterior":null,"nuevo":"escrito_presentado"},{"campo":"descripcion","anterior":null,"nuevo":"Se presenta demanda por daños y perjuicios derivados del accidente de tránsito del 12/09/2023. Se ofrece prueba documental, testimonial, pericial mecánica y pericial médica. Se cita en garantía a Seguros La Ribera S.A."},{"campo":"textoCliente","anterior":null,"nuevo":"Presentamos la demanda ante el juzgado. Le vamos a avisar cuando la empresa sea notificada."},{"campo":"visible","anterior":null,"nuevo":true},{"campo":"anulado","anterior":null,"nuevo":false}]');
INSERT INTO `movimientos` (`causaId`, `fecha`, `tipo`, `descripcion`, `textoCliente`, `visible`, `anulado`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES (@causa, '2024-04-22', 'providencia', 'Por presentada, por parte y con domicilio constituido. Córrase traslado de la demanda por el término de ley. Cítese en garantía a Seguros La Ribera S.A.', 'El juzgado dio curso a la demanda y ordenó notificar a la empresa y a su aseguradora.', 1, 0, @u_sofia, '2024-04-22 12:02:11.276822', NULL, NULL);
