INSERT INTO `movimientos` (`causaId`, `fecha`, `tipo`, `descripcion`, `textoCliente`, `visible`, `anulado`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES (@causa, '2024-06-11', 'escrito_presentado', 'Transportes del Litoral S.A. contesta demanda y niega su responsabilidad. Seguros La Ribera S.A. acepta la citación en garantía dentro de los límites de la póliza.', 'La empresa y su aseguradora contestaron la demanda. Es lo habitual: rechazan la responsabilidad. Seguimos con la etapa de prueba.', 1, 0, @u_julian, '2024-06-11 17:30:13.552644', NULL, NULL);
