INSERT INTO `movimientos` (`causaId`, `fecha`, `tipo`, `descripcion`, `textoCliente`, `visible`, `anulado`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES (@causa, '2024-08-27', 'audiencia', 'Audiencia preliminar. Sin acuerdo conciliatorio. Se abre la causa a prueba por 40 días y se proveen las pruebas ofrecidas.', 'Se realizó la audiencia en el juzgado. No hubo acuerdo y el juez abrió la etapa de prueba.', 1, 0, @u_julian, '2024-08-27 13:15:44.690555', NULL, NULL);
