INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Vizzoti, Carlos Alberto c/ AMSA S.A. s/ despido', 'Corte Suprema de Justicia de la Nación', 'laboral', '2004-09-14', 'Fallos 327:3677', 'Fallos3273677', 'El tope del art. 245 de la Ley de Contrato de Trabajo para la base de cálculo de la indemnización por despido es inconstitucional cuando su aplicación reduce en más de un 33 % la mejor remuneración mensual, normal y habitual del trabajador.\n\nEl trabajador es sujeto de preferente tutela constitucional (art. 14 bis CN) y la indemnización debe guardar una relación razonable con el salario que se toma como base.', 'https://sjconsulta.csjn.gov.ar/sjconsulta/', 1, @u_sofia, '2025-04-03 10:12:44.512331', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k1);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k2);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k3);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k4);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Aquino, Isacio c/ Cargo Servicios Industriales S.A. s/ accidentes ley 9688', 'Corte Suprema de Justicia de la Nación', 'laboral', '2004-09-21', 'Fallos 327:3753', 'Fallos3273753', 'Es inconstitucional el art. 39 inc. 1 de la Ley de Riesgos del Trabajo 24.557 en cuanto exime al empleador de responsabilidad civil.\n\nEl trabajador víctima de un accidente o de una enfermedad laboral puede reclamar la reparación integral del daño con fundamento en el derecho civil: el principio de no dañar a otro tiene raíz constitucional (art. 19 CN) y la ley no puede excluir a los trabajadores de esa protección.', NULL, 1, @u_sofia, '2025-06-03 15:40:02.009871', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k5);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k6);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k7);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k4);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Arostegui, Pablo Martín c/ Omega Aseguradora de Riesgos del Trabajo S.A. y Pametal Peluso y Compañía S.R.L.', 'Corte Suprema de Justicia de la Nación', 'laboral', '2008-04-08', 'Fallos 331:570', 'Fallos331570', 'La reparación del daño por incapacidad laboral no puede limitarse a fórmulas matemáticas que solo consideran la pérdida de ingresos. Debe valorarse a la persona de manera integral, incluidos los aspectos de su vida de relación, social, cultural y deportiva, y la pérdida de chances.', NULL, 1, @u_sofia, '2025-06-03 15:52:17.330145', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k5);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k6);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k8);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Pérez, Aníbal Raúl c/ Disco S.A.', 'Corte Suprema de Justicia de la Nación', 'laboral', '2009-09-01', 'Fallos 332:2043', 'Fallos3322043', 'Los vales alimentarios que el empleador entrega como contraprestación del trabajo tienen naturaleza salarial. Es inconstitucional el art. 103 bis inc. c de la Ley de Contrato de Trabajo en cuanto les niega ese carácter: el salario es la ganancia que obtiene el trabajador por su labor y el legislador no puede desconocerlo por vía de calificación.', NULL, 1, @u_sofia, '2025-07-15 09:05:59.770012', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k9);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k4);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Álvarez, Maximiliano y otros c/ Cencosud S.A. s/ acción de amparo', 'Corte Suprema de Justicia de la Nación', 'laboral', '2010-12-07', 'Fallos 333:2306', 'Fallos3332306', 'La ley 23.592 contra actos discriminatorios es aplicable a la relación de trabajo privada. El despido motivado en la actividad sindical del trabajador es discriminatorio y nulo, y corresponde la reinstalación en el puesto, sin que la libertad de contratar del empleador lo impida.', NULL, 1, @u_julian, '2025-07-15 09:20:11.104338', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k10);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k11);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k1);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k12);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Halabi, Ernesto c/ P.E.N. - ley 25.873 - dto. 1563/04 s/ amparo ley 16.986', 'Corte Suprema de Justicia de la Nación', 'federal', '2009-02-24', 'Fallos 332:111', 'Fallos332111', 'El art. 43 de la Constitución Nacional admite una tercera categoría de derechos: los de incidencia colectiva referentes a intereses individuales homogéneos.\n\nAnte la falta de una ley que reglamente las acciones de clase, la Corte reconoce su procedencia y fija sus requisitos: un hecho único que afecta a una pluralidad de sujetos, una pretensión centrada en los efectos comunes y la falta de justificación para promover demandas individuales. La declaración de inconstitucionalidad de la ley 25.873 y su decreto reglamentario alcanza a todo el colectivo.', 'https://sjconsulta.csjn.gov.ar/sjconsulta/', 1, @u_admin, '2025-08-01 11:31:45.006120', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k13);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k14);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k12);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k4);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Arriola, Sebastián y otros s/ causa Nº 9080', 'Corte Suprema de Justicia de la Nación', 'penal', '2009-08-25', 'Fallos 332:1963', 'Fallos3321963', 'Es inconstitucional el art. 14, segundo párrafo, de la ley 23.737, que castiga la tenencia de estupefacientes para consumo personal, cuando se realiza en condiciones que no traen aparejado un peligro concreto o un daño a derechos o bienes de terceros.\n\nLas acciones privadas que no ofenden al orden ni a la moral pública ni perjudican a terceros están exentas de la autoridad de los magistrados (art. 19 CN).', NULL, 1, @u_julian, '2025-09-02 18:10:30.481902', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k15);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k16);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k4);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('F., A. L. s/ medida autosatisfactiva', 'Corte Suprema de Justicia de la Nación', 'penal', '2012-03-13', 'Fallos 335:197', 'Fallos335197', 'El art. 86 inc. 2 del Código Penal, en su redacción vigente al momento del fallo, debía interpretarse en el sentido de que no es punible el aborto practicado respecto de todo embarazo que sea consecuencia de una violación, cualquiera sea la capacidad de la víctima.\n\nSu realización no requiere autorización judicial previa: basta la declaración jurada de la víctima o de su representante legal. La Corte exhortó a las autoridades a implementar protocolos hospitalarios para atender estos casos.', NULL, 1, @u_julian, '2025-09-02 18:25:04.777310', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k17);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k18);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k16);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Badaro, Adolfo Valentín c/ ANSeS s/ reajustes varios', 'Corte Suprema de Justicia de la Nación', 'federal', '2007-11-26', 'Fallos 330:4866', 'Fallos3304866', 'La movilidad de las jubilaciones prevista en el art. 14 bis de la Constitución Nacional es una garantía que el Congreso debe reglamentar de modo que el haber guarde una proporción razonable con los ingresos de los trabajadores activos. Ante la omisión legislativa, la Corte fijó la movilidad del haber del actor para el período reclamado según la variación del índice de salarios del INDEC.', NULL, 1, @u_admin, '2025-10-20 10:00:00.120044', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k19);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k20);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Campodónico de Beviacqua, Ana Carina c/ Ministerio de Salud y Acción Social', 'Corte Suprema de Justicia de la Nación', 'federal', '2000-10-24', 'Fallos 323:3229', 'Fallos3233229', 'El Estado Nacional tiene la obligación impostergable de garantizar el derecho a la preservación de la salud, comprendido en el derecho a la vida, con acciones positivas, sin perjuicio de las obligaciones de las jurisdicciones locales y de las obras sociales. Se ordenó continuar con la provisión gratuita de la medicación que necesitaba un niño con una grave enfermedad de la médula ósea.', NULL, 1, @u_admin, '2025-10-20 10:14:39.904551', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k18);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k12);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Siri, Ángel s/ interpone recurso de hábeas corpus', 'Corte Suprema de Justicia de la Nación', 'otro', '1957-12-27', 'Fallos 239:459', 'Fallos239459', 'Las garantías individuales existen y protegen a las personas por el solo hecho de estar consagradas en la Constitución, con independencia de las leyes reglamentarias. Ante la clausura de un diario sin orden ni causa conocida, los jueces deben restablecer de inmediato la garantía restringida. Es el fallo que dio origen a la acción de amparo contra actos de autoridad pública.', NULL, 1, @u_admin, '2026-01-08 12:00:00.000731', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k12);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k21);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Kot, Samuel S.R.L. s/ acción de amparo', 'Corte Suprema de Justicia de la Nación', 'otro', '1958-09-05', 'Fallos 241:291', 'Fallos241291', 'La acción de amparo procede también contra actos de particulares que restringen ilegítimamente derechos constitucionales, cuando la ilegitimidad es clara y manifiesta y la remisión a los procedimientos ordinarios produciría un daño grave e irreparable. Se ordenó la desocupación de una fábrica tomada por sus trabajadores durante un conflicto laboral.', NULL, 1, @u_admin, '2026-01-08 12:09:51.300218', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k12);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k22);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Sejean, Juan Bautista c/ Zaks de Sejean, Ana María', 'Corte Suprema de Justicia de la Nación', 'familia', '1986-11-27', 'Fallos 308:2268', 'Fallos3082268', 'Es inconstitucional el art. 64 de la ley 2393 de matrimonio civil, en cuanto impedía a los cónyuges divorciados recuperar su aptitud nupcial. La indisolubilidad del vínculo impuesta por la ley afecta la autonomía de la conciencia y el derecho a la privacidad (art. 19 CN). El fallo precedió a la sanción de la ley 23.515 de divorcio vincular.', NULL, 1, @u_julian, '2026-02-16 16:45:12.650009', @u_julian, '2026-02-17 09:02:03.115870');
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k23);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k16);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k4);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Gunther, Fernando Raúl c/ Gobierno Nacional (Ejército Argentino)', 'Corte Suprema de Justicia de la Nación', 'federal', '1986-08-05', 'Fallos 308:1118', 'Fallos3081118', 'El principio general que prohíbe dañar a otro tiene raíz constitucional (art. 19 CN). La reparación del daño causado a un conscripto durante el servicio militar debe ser integral: comprende la incapacidad para el trabajo y la afectación de la vida de relación, y no puede limitarse a los beneficios previstos en el régimen especial.', NULL, 1, @u_julian, '2026-03-30 11:11:11.111111', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k6);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k24);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k25);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Rodríguez, María Belén c/ Google Inc. s/ daños y perjuicios', 'Corte Suprema de Justicia de la Nación', 'civil', '2014-10-28', 'Fallos 337:1174', 'Fallos3371174', 'Los motores de búsqueda en internet no tienen una obligación general de monitorear los contenidos que suben terceros. Responden por culpa, cuando toman efectivo conocimiento de la ilicitud de un contenido y no actúan con diligencia para bloquearlo.\n\nSi la ilicitud es manifiesta, basta la notificación privada del damnificado; si requiere un esclarecimiento, hace falta una notificación judicial o administrativa.', 'https://sjconsulta.csjn.gov.ar/sjconsulta/', 1, @u_sofia, '2026-05-05 17:30:00.402117', NULL, NULL);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k25);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k26);
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k27);
INSERT INTO `fallos` (`caratula`, `tribunal`, `fuero`, `fecha`, `numero`, `numeroBusqueda`, `sumario`, `enlace`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Vizotti, Carlos c/ AMSA s/ despido', 'Corte Suprema de Justicia de la Nación', 'laboral', '2004-09-14', NULL, NULL, 'Tope del art. 245 LCT. Ver el fallo cargado con la carátula correcta.', NULL, 0, @u_sofia, '2025-04-03 10:05:20.000400', @u_sofia, '2025-04-03 10:13:01.230000');
INSERT INTO `fallo_palabras_clave` (`falloId`, `palabraClaveId`) VALUES (@fallo, @k1);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Demanda de daños y perjuicios por accidente de tránsito', 'demanda', 'civil', 'Demanda completa con citación en garantía de la aseguradora. Completar los hechos, los rubros y la prueba.', 'PROMUEVE DEMANDA DE DAÑOS Y PERJUICIOS\n\nSr. Juez:\n\n#ACTORES_CON_DOCUMENTO#, por derecho propio, con domicilio real en #CLIENTES_DOMICILIO#, con el patrocinio letrado de #ABOGADO_RESPONSABLE#, a V.S. respetuosamente me presento y digo:\n\nI. OBJETO\nQue vengo a promover demanda por daños y perjuicios contra #DEMANDADOS_CON_DOCUMENTO#, por la suma de $ ______ o lo que en más o en menos resulte de la prueba, con más intereses y costas. Solicito además la citación en garantía de ______ en los términos del art. 118 de la ley 17.418.\n\nII. HECHOS\nEl día ______, siendo aproximadamente las ______ horas, circulaba por ______ cuando el vehículo dominio ______, conducido por ______, me embistió en ______.\n\nIII. DAÑOS RECLAMADOS\na) Incapacidad sobreviniente: $ ______\nb) Gastos médicos y de farmacia: $ ______\nc) Daño moral: $ ______\nd) Daños al vehículo: $ ______\n\nIV. DERECHO\nFundo el derecho en los arts. 1716, 1721, 1737, 1757 y 1769 del Código Civil y Comercial de la Nación.\n\nV. PRUEBA\na) Documental: denuncia policial, fotografías, presupuestos y constancias médicas.\nb) Testimonial: ______\nc) Pericial médica y pericial mecánica.\nd) Informativa: ______\n\nVI. PETITORIO\n1. Me tenga por presentado, por parte y con domicilio constituido.\n2. Corra traslado de la demanda y cite en garantía a la aseguradora.\n3. Oportunamente, haga lugar a la demanda con costas.\n\nProveer de conformidad,\nSERÁ JUSTICIA.\n\n#FECHA_EN_LETRAS#', 1, @u_julian, '2025-03-04 10:00:00.250000', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Contestación de demanda con negativa general', 'contestacion_demanda', 'civil', 'Estructura básica de contestación. Detallar las negativas particulares y la versión de los hechos.', 'CONTESTA DEMANDA\n\nSr. Juez:\n\n#ABOGADO_RESPONSABLE#, en representación de #DEMANDADOS_CON_DOCUMENTO#, según poder que acompaño, en los autos "#CARATULA#", Expte. Nº #NUMERO_EXPEDIENTE#, a V.S. respetuosamente digo:\n\nI. OBJETO\nQue vengo en tiempo y forma a contestar la demanda promovida por #ACTORES#, y solicito su rechazo con costas.\n\nII. NEGATIVA GENERAL Y PARTICULAR\nNiego todos y cada uno de los hechos afirmados en la demanda que no sean objeto de un expreso reconocimiento en este escrito. En particular, niego:\na) ______\nb) ______\n\nIII. LA VERDAD DE LOS HECHOS\n______\n\nIV. PRUEBA\na) Documental: ______\nb) Testimonial: ______\n\nV. PETITORIO\n1. Me tenga por presentado, por parte y con domicilio constituido.\n2. Tenga por contestada la demanda en tiempo y forma.\n3. Oportunamente, rechace la demanda con costas a la actora.\n\nProveer de conformidad,\nSERÁ JUSTICIA.', 1, @u_julian, '2025-03-04 10:30:00.004000', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Demanda laboral por despido sin causa', 'demanda', 'laboral', 'Reclamo de indemnizaciones de los arts. 232, 233 y 245 LCT y multa de la ley 25.323.', 'PROMUEVE DEMANDA LABORAL\n\nSr. Juez:\n\n#ACTORES_CON_DOCUMENTO#, con domicilio real en #CLIENTES_DOMICILIO#, con el patrocinio letrado de #ABOGADO_RESPONSABLE#, a V.S. me presento y digo:\n\nI. OBJETO\nQue vengo a promover demanda contra #DEMANDADOS_CON_DOCUMENTO# por el cobro de la suma de $ ______ en concepto de indemnización por antigüedad (art. 245 LCT), preaviso (art. 232 LCT), integración del mes de despido (art. 233 LCT), vacaciones y SAC proporcionales y multa del art. 2 de la ley 25.323, o lo que en más o en menos resulte de la prueba, con intereses y costas.\n\nII. HECHOS\nIngresé a trabajar a las órdenes de la demandada el ______, cumpliendo tareas de ______ con una jornada de ______. Mi mejor remuneración mensual, normal y habitual fue de $ ______.\nEl ______ fui despedido sin expresión de causa mediante ______.\n\nIII. LIQUIDACIÓN\n______\n\nIV. DERECHO\nFundo el derecho en el art. 14 bis de la Constitución Nacional, en los arts. 232, 233 y 245 de la Ley de Contrato de Trabajo y en la ley 25.323.\n\nV. PRUEBA\na) Documental: telegramas, recibos de sueldo y certificado de trabajo.\nb) Informativa: oficio a ANSES.\nc) Testimonial: ______\nd) Pericial contable.\n\nVI. PETITORIO\n1. Me tenga por presentado, por parte y con domicilio constituido.\n2. Corra traslado de la demanda.\n3. Oportunamente, haga lugar a la demanda con costas.\n\nProveer de conformidad,\nSERÁ JUSTICIA.\n\n#FECHA_EN_LETRAS#', 1, @u_sofia, '2025-03-12 16:05:00.810000', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Oficio a ANSES - informe de aportes', 'oficio', 'laboral', NULL, 'OFICIO\n\nAl Sr. Gerente de la Administración Nacional de la Seguridad Social (ANSES)\nS/D\n\nEn los autos caratulados "#CARATULA#", Expte. Nº #NUMERO_EXPEDIENTE#, que tramitan ante el #JUZGADO#, se ha dispuesto librar el presente a fin de que, en el plazo de diez (10) días, informe:\n\na) Los aportes y contribuciones registrados a nombre de #ACTORES_CON_DOCUMENTO# en los últimos diez años.\nb) Los empleadores que los efectuaron y los períodos correspondientes.\nc) Las remuneraciones declaradas en cada período.\n\nQueda autorizado para su diligenciamiento #ABOGADO_RESPONSABLE#.\n\nSaludo a Ud. atentamente.\n\n#FECHA#', 1, @u_sofia, '2025-08-12 10:30:00.000000', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Petición de divorcio con propuesta reguladora', 'demanda', 'familia', 'Petición unilateral (arts. 437 y 438 CCyC). Completar los datos del matrimonio y la propuesta.', 'SOLICITA DIVORCIO - PROPUESTA REGULADORA\n\nSr. Juez:\n\n#ACTORES_CON_DOCUMENTO#, con domicilio real en #CLIENTES_DOMICILIO#, con el patrocinio letrado de #ABOGADO_RESPONSABLE#, a V.S. me presento y digo:\n\nI. OBJETO\nQue vengo a peticionar el divorcio respecto de #DEMANDADOS_CON_DOCUMENTO#, en los términos de los arts. 437 y 438 del Código Civil y Comercial de la Nación.\n\nII. DATOS DEL MATRIMONIO\nContrajimos matrimonio el ______ en ______, según acta que acompaño. De la unión nacieron ______.\nEl último domicilio conyugal fue en ______.\n\nIII. PROPUESTA REGULADORA\na) Atribución de la vivienda: ______\nb) Cuidado personal de los hijos: ______\nc) Régimen de comunicación: ______\nd) Alimentos: ______\ne) Distribución de los bienes: ______\n\nIV. PETITORIO\n1. Me tenga por presentado, por parte y con domicilio constituido.\n2. Corra traslado de la propuesta al otro cónyuge.\n3. Oportunamente, decrete el divorcio.\n\nProveer de conformidad,\nSERÁ JUSTICIA.', 1, @u_julian, '2025-02-03 18:20:00.333000', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Solicita suspensión del juicio a prueba', 'escrito_tramite', 'penal', 'Pedido de probation (art. 76 bis CP) con ofrecimiento de reparación.', 'SOLICITA SUSPENSIÓN DEL JUICIO A PRUEBA\n\nSr. Juez:\n\n#ABOGADO_RESPONSABLE#, abogado defensor de #CLIENTES_CON_DOCUMENTO#, en la causa "#CARATULA#", Expte. Nº #NUMERO_EXPEDIENTE#, a V.S. respetuosamente digo:\n\nI. OBJETO\nQue vengo a solicitar la suspensión del juicio a prueba en favor de mi defendido, en los términos del art. 76 bis del Código Penal.\n\nII. PROCEDENCIA\nEl delito imputado tiene prevista una pena cuyo máximo no excede de tres años de prisión, mi defendido carece de antecedentes penales y las circunstancias del caso permitirían dejar en suspenso una eventual condena.\n\nIII. OFRECIMIENTO DE REPARACIÓN\nMi defendido ofrece, en concepto de reparación del daño y en la medida de sus posibilidades, la suma de $ ______, pagadera en ______.\n\nIV. REGLAS DE CONDUCTA\nSe compromete a cumplir las reglas de conducta que V.S. disponga conforme al art. 27 bis del Código Penal.\n\nV. PETITORIO\n1. Se fije audiencia para tratar este pedido.\n2. Oportunamente, se conceda la suspensión del juicio a prueba.\n\nProveer de conformidad,\nSERÁ JUSTICIA.', 1, @u_julian, '2025-11-19 20:10:00.900000', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Interpone recurso de apelación', 'recurso', 'otro', 'Sirve para cualquier fuero. Completar la fecha de la resolución y de la notificación.', 'INTERPONE RECURSO DE APELACIÓN\n\nSr. Juez:\n\n#ABOGADO_RESPONSABLE#, letrado apoderado de #CLIENTES#, en los autos caratulados "#CARATULA#", Expte. Nº #NUMERO_EXPEDIENTE#, a V.S. respetuosamente digo:\n\nQue vengo en legal tiempo y forma a interponer recurso de apelación contra la resolución de fecha ______, notificada el ______, por resultar gravosa a los intereses de mi parte.\n\nSolicito que se conceda el recurso libremente y con efecto suspensivo, y que oportunamente se eleven los autos al Superior.\n\nProveer de conformidad,\nSERÁ JUSTICIA.', 1, @u_admin, '2025-01-20 09:00:00.000100', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Solicita pronto despacho', 'escrito_tramite', 'otro', NULL, 'SOLICITA PRONTO DESPACHO\n\nSr. Juez:\n\n#ABOGADO_RESPONSABLE#, por la representación de #CLIENTES# en los autos "#CARATULA#", Expte. Nº #NUMERO_EXPEDIENTE#, a V.S. digo:\n\nQue, habiendo vencido el plazo para resolver la cuestión planteada en el escrito de fecha ______, vengo a solicitar pronto despacho.\n\nProveer de conformidad,\nSERÁ JUSTICIA.', 1, @u_admin, '2025-01-20 09:10:00.000200', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Constituye nuevo domicilio electrónico', 'escrito_tramite', 'otro', 'Cambiar la casilla de ejemplo por la del estudio.', 'CONSTITUYE NUEVO DOMICILIO ELECTRÓNICO\n\nSr. Juez:\n\n#ABOGADO_RESPONSABLE#, en los autos "#CARATULA#", Expte. Nº #NUMERO_EXPEDIENTE#, a V.S. digo:\n\nQue vengo a constituir nuevo domicilio electrónico en la casilla estudio@estudiomuestra.test, donde se tendrán por válidas todas las notificaciones que se cursen en adelante.\n\nProveer de conformidad,\nSERÁ JUSTICIA.', 1, @u_admin, '2025-01-20 09:20:00.000300', @u_admin, '2026-03-02 10:00:00.000000');
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Cédula de notificación', 'cedula', 'otro', 'Completar el destinatario, el domicilio y la resolución que se notifica.', 'CÉDULA DE NOTIFICACIÓN\n\nDestinatario: ______\nDomicilio: ______\nCarácter del domicilio: ______\n\nJuzgado: #JUZGADO#\nAutos: "#CARATULA#"\nExpte. Nº: #NUMERO_EXPEDIENTE#\n\nHago saber a Ud. que en los autos indicados se ha dictado la siguiente resolución: "______".\n\nQueda Ud. debidamente notificado.\n\n#FECHA#', 1, @u_sofia, '2025-04-01 12:00:00.000000', NULL, NULL);
INSERT INTO `modelos_escritos` (`titulo`, `tipo`, `fuero`, `descripcion`, `texto`, `activo`, `creadoPorId`, `creadoEn`, `modificadoPorId`, `modificadoEn`) VALUES ('Acompaña bono y tasa de justicia (versión anterior)', 'escrito_tramite', 'otro', 'Reemplazado: ya no se usa.', 'ACOMPAÑA BONO Y TASA DE JUSTICIA\n\nSr. Juez:\n\n#ABOGADO_RESPONSABLE#, en los autos "#CARATULA#", a V.S. digo:\n\nQue vengo a acompañar el bono de derecho fijo y la constancia de pago de la tasa de justicia.\n\nProveer de conformidad,\nSERÁ JUSTICIA.', 0, @u_admin, '2024-02-01 10:00:00.000000', @u_admin, '2025-01-20 09:30:00.000000');
